function validateHighSchoolEntryCapability(target) {
  const errors = [];
  if (target?.characterGenesis?.completed !== true) errors.push("character-genesis-incomplete");
  CHARACTER_GENESIS_ABILITY_KEYS.forEach(key => {
    const value = target?.characterGenesis?.finalAbilities?.[key];
    if (!Number.isFinite(value) || value < 1 || value > 5) errors.push(`finalized-genesis-invalid:${key}`);
  });
  if (!PlayerIdentityOptions.idealSelf.includes(target?.idealSelf)) errors.push("ideal-self-invalid");
  if (!PlayerIdentityOptions.bats.includes(target?.bats) || !PlayerIdentityOptions.throws.includes(target?.throws)) errors.push("handedness-invalid");
  if (target?.capabilityState?.initialized !== true) errors.push("capability-not-settled");
  if (target?.capabilityState?.initialSkillFormulaVersion !== INITIAL_SKILL_FORMULA_VERSION) errors.push("initial-formula-version-invalid");
  if (target?.capabilityState?.settlementVersion !== HS_ENTRY_CAPABILITY_SETTLEMENT_VERSION) errors.push("settlement-version-invalid");
  UNIVERSAL_BASEBALL_SKILL_KEYS.forEach(skill => {
    const value = target?.baseballSkills?.[skill];
    if (!Number.isFinite(value) || value < 1 || value > 20) errors.push(`universal-skill-invalid:${skill}`);
  });
  SPECIALIST_BASEBALL_SKILL_KEYS.forEach(skill => {
    const value = target?.baseballSkills?.[skill];
    if (!Number.isFinite(value) || value < 0 || value > 20) errors.push(`specialist-skill-invalid:${skill}`);
  });
  return { ok: errors.length === 0, errors };
}

function settleHighSchoolEntryCapability(target, options = {}) {
  const state = ensureCapabilityStateShape(target);
  if (state.initialized && state.settlementVersion === HS_ENTRY_CAPABILITY_SETTLEMENT_VERSION) {
    const validation = validateHighSchoolEntryCapability(target);
    return validation.ok ? { ok: true, existing: true, capabilityState: state } : { ok: false, error: "既有高中能力結算不合法。", validation };
  }
  if (!target?.characterGenesis?.completed) return { ok: false, error: "Character Genesis 未完成，不能進行高中能力結算。" };
  if (!Object.keys(state.initialBaseballSkills || {}).length) {
    const initialized = initializePlayerCapabilityFromGenesis(target);
    if (!initialized.ok) return initialized;
  }
  const activeState = ensureCapabilityStateShape(target);
  target.baseballSkills = Object.assign({}, createInitialPlayer().baseballSkills, target.baseballSkills || {});
  UNIVERSAL_BASEBALL_SKILL_KEYS.forEach(skill => {
    const current = Number(target.baseballSkills[skill]);
    const initial = Number(activeState.initialBaseballSkills[skill]);
    target.baseballSkills[skill] = Math.max(1, Math.min(20, Number.isFinite(current) && current > 0 ? current : initial));
  });
  SPECIALIST_BASEBALL_SKILL_KEYS.forEach(skill => {
    const current = Number(target.baseballSkills[skill]);
    target.baseballSkills[skill] = Math.max(0, Math.min(20, Number.isFinite(current) ? current : 0));
  });
  const affinityExperienceMap = { infield: "內野手", outfield: "外野手", catcher: "捕手", pitcher: "投手" };
  Object.entries(affinityExperienceMap).forEach(([affinity, position]) => {
    const value = Number(target.positionAffinity?.[affinity]);
    if (Number.isFinite(value) && value > 0 && !Number.isFinite(Number(activeState.positionExperience[position]))) {
      activeState.positionExperience[position] = Math.min(20, value);
    }
  });
  if (target.baseballSkills.blocking > 0 || target.baseballSkills.gameCalling > 0) {
    const missingCatcherExperience = !(Number(activeState.specialistExperience.catcher) > 0);
    activeState.specialistExperience.catcher = Math.max(1, Number(activeState.specialistExperience.catcher) || 0);
    if (missingCatcherExperience) recordLegacySpecialistNormalization(target, "catcher", ["blocking", "gameCalling"].filter(skill => target.baseballSkills[skill] > 0));
  }
  if (target.baseballSkills.control > 0 || target.baseballSkills.pitchStamina > 0) {
    const missingPitcherExperience = !(Number(activeState.specialistExperience.pitcher) > 0);
    activeState.specialistExperience.pitcher = Math.max(1, Number(activeState.specialistExperience.pitcher) || 0);
    if (missingPitcherExperience) recordLegacySpecialistNormalization(target, "pitcher", ["control", "pitchStamina"].filter(skill => target.baseballSkills[skill] > 0));
  }
  activeState.initialized = true;
  activeState.initialSkillFormulaVersion = INITIAL_SKILL_FORMULA_VERSION;
  activeState.settlementVersion = HS_ENTRY_CAPABILITY_SETTLEMENT_VERSION;
  activeState.originType = options.originType || activeState.originType || "normal-youth-outcomes";
  activeState.developmentProfile = {
    originIdealSelf: target.idealSelf,
    biasTags: Object.keys(IDEAL_SELF_STARTING_BIASES[target.idealSelf] || {})
  };
  activeState.provenance.settlement = {
    version: HS_ENTRY_CAPABILITY_SETTLEMENT_VERSION,
    formulaVersion: INITIAL_SKILL_FORMULA_VERSION,
    originType: activeState.originType,
    youthOutcomeCount: activeState.youthOutcomes.length,
    ledgerEntryCount: activeState.provenance.capabilityLedger.length,
    universalMinimum: 1,
    specialistZeroAllowed: true
  };
  const validation = validateHighSchoolEntryCapability(target);
  if (!validation.ok) {
    activeState.initialized = false;
    return { ok: false, error: "高中能力結算 validation failed。", validation };
  }
  return { ok: true, existing: false, capabilityState: activeState };
}

function createRepresentativeHighSchoolEntryFixture(profile = "ordinary", seed = 1) {
  const profiles = {
    ordinary: { idealSelf: "全能型", allocation: { ballSense: 1, observe: 1, fitness: 0, batting: 0, baseRunning: 0, baseballIQ: 1 } },
    defense: { idealSelf: "守備型", allocation: { ballSense: 1, observe: 1, fitness: 1, batting: 0, baseRunning: 0, baseballIQ: 0 } },
    batting: { idealSelf: "強打型", allocation: { ballSense: 1, observe: 0, fitness: 0, batting: 2, baseRunning: 0, baseballIQ: 0 } },
    low: { idealSelf: "棒球理解型", allocation: { ballSense: 0, observe: 0, fitness: 0, batting: 0, baseRunning: 1, baseballIQ: 2 } }
  };
  const config = profiles[profile] || profiles.ordinary;
  let randomState = Math.max(1, Number(seed) >>> 0);
  const random = () => {
    randomState = (Math.imul(randomState, 1664525) + 1013904223) >>> 0;
    return randomState / 4294967296;
  };
  const target = createInitialPlayer(`代表性高中球員-${profile}-${seed}`);
  target.origin = "understand";
  target.idealSelf = config.idealSelf;
  const roll = rollCharacterGenesis(random);
  const genesis = applyCharacterGenesis(target, { baseRoll: roll.baseRoll, allocation: config.allocation, shape: roll.shape, bats: "R", throws: "R" });
  if (!genesis.ok) throw new Error(genesis.error);
  applyCanonicalPositionProfile(target, "內野手", []);
  applySyntheticYouthOrigin(target);
  const settlement = settleHighSchoolEntryCapability(target, { originType: `representative-${profile}` });
  if (!settlement.ok) throw new Error(settlement.error);
  target.chapter = "青棒";
  target.age = 16;
  target.highSchoolStep = 5;
  target.highSchoolRoleCode = profile === "low" ? "bench" : "rotation";
  return target;
}

function getDefensiveSimulationCapability(subject = player, position = player.primaryPosition, matchContext = subject?.highSchoolMatch) {
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ fielding: subject.defense, reaction: subject.defense, range: subject.defense, arm: subject.arm, throwing: subject.arm, decision: Math.round((subject.defense + subject.contact) / 2) });
  }
  const rawSkills = subject.baseballSkills || {};
  const activeMatch = matchContext || (subject === player ? player.highSchoolMatch : null);
  const audit = getDevelopmentMatchPositionTestCapabilityAudit(subject, activeMatch);
  const skills = audit.active && !activeMatch?.completed
    ? Object.fromEntries(Object.keys(rawSkills).map(skill => [skill, audit.skills[skill]?.effective ?? rawSkills[skill]]))
    : rawSkills;
  const effectivePosition = audit.active ? audit.position : position;
  const positionTools = {
    "內野手": ["catching", "reaction", "throwing"],
    "外野手": ["catching", "range", "armStrength"],
    "捕手": ["blocking", "gameCalling", "throwing"],
    "投手": ["control", "reaction", "throwing"]
  }[position] || ["catching", "reaction", "throwing"];
  const values = positionTools.map(key => Number(skills[key]) || 0);
  const reactionSkill = Number(skills.reaction) || values[1] || 0;
  const throwingSkill = values[2] || 0;
  const armSkill = ["游擊手", "三壘手"].includes(effectivePosition) ? Number(skills.armStrength) || throwingSkill : throwingSkill;
  return Object.freeze({
    fielding: Math.round((values[0] * 2 + values[1] + (Number(subject.ballSense) || 0)) / 4),
    reaction: Math.round((reactionSkill * 2 + (Number(subject.ballSense) || 0)) / 3),
    range: Math.round(((Number(skills.range) || reactionSkill) * 2 + (Number(subject.fitness) || 0)) / 3),
    arm: Math.round((armSkill * 2 + (Number(subject.fitness) || 0)) / 3),
    throwing: Math.round((throwingSkill * 2 + (Number(subject.observe) || 0)) / 3),
    decision: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function assertHighSchoolMatchCapabilityAdmission(subject = player) {
  const validation = validateHighSchoolEntryCapability(subject);
  if (!validation.ok) {
    throw new Error(`正式高中比賽拒絕未完成 Capability Settlement 的球員：${validation.errors.join(",")}`);
  }
  return true;
}

function createHighSchoolRosterPlayerActor(subject = player, playerPosition = subject?.primaryPosition) {
  const highSchoolYear = Number(subject?.highSchoolYearTransitionState?.currentHighSchoolYear)
    || Math.max(1, Math.min(3, (Number(subject?.age) || 16) - 15));
  return {
    id: "player", name: subject?.name || "你", age: subject?.age,
    year: highSchoolYear,
    primaryPosition: playerPosition, secondaryPositions: subject?.secondaryPositions || [],
    bats: subject?.bats, throws: subject?.throws,
    simulationCapability: {
      offense: getOffensiveSimulationCapability(subject),
      defense: getDefensiveSimulationCapability(subject, playerPosition)
    }
  };
}

function materializeSelectedHighSchoolRoster(subject = player, options = {}) {
  if (typeof HighSchoolEntryRosterContext === "undefined" || typeof TeamRosterFoundation === "undefined") return null;
  const state = subject?.schoolInvitationState;
  const invitation = getSelectedSchoolInvitation(subject);
  const baseRoster = state?.selectedBaseRoster || invitation?.baseRoster;
  if (!baseRoster || !TeamRosterFoundation.validateRoster(baseRoster).ok) return null;
  const invitationPosition = invitation?.positionCompetitionContext?.position || invitation?.schoolInterest?.candidatePosition || "";
  const rawPosition = options.playerPosition || subject?.primaryPosition || invitationPosition;
  const normalizedRequested = TeamRosterFoundation.normalizePosition(rawPosition);
  const requestedPosition = ["內野手", "外野手"].includes(rawPosition) && invitationPosition
    ? TeamRosterFoundation.normalizePosition(invitationPosition) : normalizedRequested;
  const rosterRole = options.rosterRole === "starter" ? "starter" : "bench";
  const selectedRoster = HighSchoolEntryRosterContext.injectPlayerIntoSelectedRoster(
    baseRoster,
    createHighSchoolRosterPlayerActor(subject, requestedPosition),
    { playerRole: rosterRole, playerPosition: requestedPosition }
  );
  const playerCapability = HighSchoolEntryRosterContext.getPositionCapability(
    selectedRoster.players.find(actor => actor.id === "player"), requestedPosition
  );
  const invitationCompetition = invitation?.positionCompetitionContext;
  const competition = options.refreshCompetition !== true && invitationCompetition?.position === requestedPosition
    ? cloneSchoolInvitationValue(invitationCompetition)
    : HighSchoolEntryRosterContext.deriveCompetitionContext(baseRoster, requestedPosition, playerCapability);
  const activeRosterIdentity = state.selectedSchoolYearRosterIdentity || invitation.schoolYearRosterIdentity;
  state.selectedSchoolYearRosterIdentity = cloneSchoolInvitationValue(activeRosterIdentity);
  state.selectedBaseRoster = cloneSchoolInvitationValue(baseRoster);
  state.selectedSchoolRoster = cloneSchoolInvitationValue(selectedRoster);
  state.selectedPositionCompetitionContext = cloneSchoolInvitationValue(competition);
  state.selectedPlayerInjectionState = {
    ...cloneSchoolInvitationValue(selectedRoster.playerInjection),
    status: "injected",
    schoolYearRosterIdentity: activeRosterIdentity.identity
  };
  return selectedRoster;
}

function classifyPositionFamilyPlay(situation, legalChoices = [], playerInvolved = true) {
  if (!playerInvolved) return Object.freeze({ eventClassification: "ordinaryPlay", decisionTension: "none" });
  const gate = evaluatePositionDecisionMoment(situation, legalChoices);
  return Object.freeze({
    eventClassification: gate.shouldCreateDecision ? "playerMeaningfulDecision" : "playerRoutinePlay",
    decisionTension: gate.decisionTension,
    gate
  });
}

function classifyHighSchoolMatchDefensiveOpportunity(match, situation, legalChoices = [], playerInvolved = true) {
  const classification = classifyPositionFamilyPlay(situation, legalChoices, playerInvolved);
  const density = evaluateHighSchoolMatchDefensiveDecisionDensity(match, situation, legalChoices, classification);
  if (classification.eventClassification !== "playerMeaningfulDecision" || density.allowed) {
    return Object.freeze({ ...classification, density });
  }
  return Object.freeze({
    eventClassification: "playerRoutinePlay",
    decisionTension: "low",
    gate: classification.gate,
    density
  });
}

function resolveHighSchoolCanonicalSecure(match, state, roll) {
  const reachResult = state?.defensiveAccess?.reachResolution;
  if (!reachResult || typeof DefensiveReachSecureFoundation === "undefined") return null;
  return DefensiveReachSecureFoundation.resolveSecure({ physicalTruth: state.physicalTruth,
    opportunity: getHighSchoolDefensiveOpportunity(match, state.physicalTruth),
    activeRoster: match.rosters[match.defenseTeam], capabilities: state.defensiveAccess.secureCapabilities,
    reachResult, roll });
}

function resolveRoutineDefensivePlay(match, situation = match?.defensiveSituation, randomSource = null, options = {}) {
  if (!match || situation?.familyId !== "infield") return null;
  if (situation.groundBallDefensiveContext?.supported) {
    assertHighSchoolGroundParticipant(match);
  }
  const legalChoices = infieldDecisionFamily.generateLegalChoices(situation, match);
  const classification = classifyPositionFamilyPlay(situation, legalChoices, true);
  if (classification.eventClassification !== "playerRoutinePlay" && options.densitySuppressed !== true) return null;
  const source = randomSource === null ? () => nextHighSchoolMatchSimulationRandom(match) : randomSource;
  const routineChoice = situation.groundBallDefensiveContext?.firstBaseContext && legalChoices[0]?.routeId === "pitcherCoverFirst"
    ? legalChoices[0] : legalChoices.find(choice => choice.routeId === "coverSecondFor643") || legalChoices.find(choice => choice.matchDecision === "secure") || legalChoices[0];
  const resolution = routineChoice ? infieldDecisionFamily.resolve(situation, routineChoice.matchDecision, match, source) : null;
  if (!resolution) return null;
  return Object.freeze({
    ...resolution,
    // Density suppression already admitted this execution as a routine play.
    // Reusing the candidate's meaningful label would make routine settlement reject it.
    eventClassification: "playerRoutinePlay",
    decisionTension: classification.decisionTension,
    executionRoute: resolution.firstBaseEvidence ? routineChoice.route : getInfieldRoutineExecutionRoute(situation)
  });
}

function buildHighSchoolShortstopExecution(match, situation, choice, sample) {
  const handoff = match.groundBallInPlayState;
  if (!Number.isFinite(sample) || sample < 0 || sample >= 1) throw new Error("Invalid SS execution sample");
  assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "SS", "player");
  if (situation.playerPosition !== "游擊手" || !handoff.supported) throw new Error("Invalid SS production context");
  const secureResolution = resolveHighSchoolCanonicalSecure(match, handoff, sample);
  const input = getHighSchoolControlledDecisionInput(match, { ...handoff, secureResolution });
  const opportunity = DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input);
  const controlled = opportunity.status === "controlledDecision";
  const selection = controlled ? DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, choice.routeId, input) : null;
  const thrown = selection ? DefensiveDecisionThrowFoundation.resolveThrow({ input, opportunity, selection,
    capabilities: { defenderId: "player", arm: situation.playerCapabilities.arm, throwing: situation.playerCapabilities.throwing },
    transferState: secureResolution.secureQuality === "bobbleButControlled" ? "delayed" : "ready" }) : null;
  const swing = (sample - 0.5) * 4;
  const receiver = selection?.route.receiverPosition
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], selection.route.receiverPosition) : null;
  const receiverCapabilities = receiver ? getDefensiveSimulationCapability(receiver, receiver.position, match) : {};
  const receiverReady = Boolean(receiver && (Number(receiverCapabilities.fielding) || 5) + swing >= 3.2);
  input.receiverState = { receiverId: receiver?.id || null, ready: receiverReady, atBase: true, tagAvailable: receiverReady, tagDelay: 1 };
  const decisionThrowState = { opportunity, preControlIntent: choice.routeId, selection, activeSelection: selection, throwResolution: thrown };
  // Failed acquisition has no controlled decision or throw. Preserve the existing
  // Foundation's no-contest diagnostic so lifecycle recovery still has an owner.
  let runnerThrowTiming = selection ? null : DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({
    stage: decisionThrowState, runnerState: null, windowState: "expired", receiverFact: "unavailable" });
  let firstLegSettlement = null;
  if (selection) {
    const timingArgs = { input, opportunity, selection, throwResolution: thrown,
      runnerState: input.runnerPhysicalStates.find(r => r.runnerId === selection.route.targetRunnerId),
      receiverState: input.receiverState, resolveThirdOut: resolveHighSchoolThirdOutIntegrity };
    runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.resolveTiming(timingArgs);
    firstLegSettlement = DefensiveRunnerThrowSettlementFoundation.deriveSettlement({ ...timingArgs, timing: runnerThrowTiming });
  }
  const firstOut = firstLegSettlement?.outRecorded === true;
  const continuationWindow = handoff.timingWindows.relayToFirstWindow.state;
  const isDoublePlay = choice.infieldRoute === "doublePlay";
  // Relay completion reuses the established 2B/SS receive-turn-deliver model.
  const relay = resolveInfieldRelayToFirst(situation, firstOut, sample, continuationWindow, receiverCapabilities);
  const secondOut = isDoublePlay && firstOut && situation.outs < 2 && relay.secondOutAvailable;
  const retirements = firstOut ? [{ runnerId: selection.route.targetRunnerId, targetBase: selection.route.targetBase,
    outType: firstLegSettlement.playType === "batterRunner" ? "batterRunnerBeforeFirst" : firstLegSettlement.playType === "force" ? "force" : "nonForceTag", sequence: 1 }] : [];
  if (secondOut) retirements.push({ runnerId: situation.batterId, targetBase: "first", outType: "batterRunnerBeforeFirst", sequence: 2 });
  // Complete all committed actors after the first-leg contest. The existing force
  // owner accounts for in-transit runners, collisions, and force removal after outs.
  const runnerSettlement = ForceAdvancement.settleForceAdvancement({ forceChain: situation.forceChain,
    movementIntents: situation.movementIntents, retirements });
  const error = (secureResolution.attemptAvailable && !secureResolution.secured) || thrown?.throwQuality === "offline";
  const resultCode = secondOut ? "twoOuts" : firstOut ? "oneOut" : error ? "error" : "zeroOuts";
  const detailedResult = secondOut ? "completedDoublePlay" : firstOut ? (isDoublePlay ? "secondStageExpired" : "cleanOut")
    : error ? (secureResolution.secured ? "inaccurateThrow" : "fieldingError") : !secureResolution.secured ? "lateFielding"
      : choice.infieldRoute === "controlledNoThrow" ? "controlledNoThrow" : "lateThrow";
  const primaryCause = !secureResolution.secured ? "playerFieldingControl" : thrown?.throwQuality === "offline" ? "playerFirstThrow"
    : !receiverReady && selection?.route.action !== "holdBall"
      ? selection?.route.receiverPosition === "1B" ? "teammateFirstBaseReceive" : selection?.route.receiverPosition === "C" ? "teammateHomeReceive" : "teammatePivot"
      : isDoublePlay && firstOut && !relay.turn && situation.batterSpeed < 8 && continuationWindow !== "narrow" ? "teammatePivot"
        : isDoublePlay && firstOut && relay.turn && !relay.firstBaseReceive ? "teammateFirstBaseReceive"
          : choice.infieldRoute === "controlledNoThrow" ? "balancedExecution"
            : !firstOut || (isDoublePlay && !secondOut) ? "timingWindow" : "balancedExecution";
  const resolution = attachDefensiveOutcomeExplanation(situation, choice, {
    familyId: "infield", route: choice.infieldRoute, routeId: choice.routeId, initialRoute: choice.routeId, activeRoute: choice.routeId,
    playerRole: "initiator", responsibility: situation.responsibility, resultCode, detailedResult,
    tier: secondOut ? "strong" : firstOut || choice.infieldRoute === "controlledNoThrow" ? "mixed" : "failure",
    decisionQuality: choice.advisable === "strong" ? "strong" : choice.advisable === "aggressive" ? "aggressive" : choice.advisable === "conservative" ? "conservative" : "reasonable",
    executionQuality: firstOut ? (isDoublePlay && !secondOut ? "partial" : "complete") : error ? "misplay" : choice.infieldRoute === "controlledNoThrow" ? "controlled" : "late",
    runnerSettlement, runnerSettlementIdentity: situation.runnerSettlementIdentity, outsCreated: runnerSettlement.outsCreated,
    runnerChanges: runnerSettlement.runnerChanges, runnersAfter: runnerSettlement.runnersAfter,
    scoringRunnerIds: runnerSettlement.scoringRunnerIds, runsAllowed: runnerSettlement.runsAllowed, error,
    primaryCause, secondaryCause: "", responsibleActor: primaryCause.startsWith("teammate") ? "teammate" : primaryCause === "timingWindow" ? "timingWindow" : "player",
    playerResponsibility: error ? "major" : "handled", teammateResponsibility: primaryCause.startsWith("teammate") ? "major" : isDoublePlay ? "shared" : "none",
    causeExplanation: primaryCause === "teammatePivot" ? "傳球的接球端未完成接球或轉傳；二壘手與游擊手的責任分開記錄。"
      : primaryCause === "teammateFirstBaseReceive" ? "傳球已進入一壘接球位置，但一壘手未完成接球；傳球與接球責任分開記錄。" : getSecondBaseCauseExplanation(primaryCause, ""),
    playerLeg: { reach: handoff.defensiveAccess.reachResolution.reached ? "completed" : "late",
      control: secureResolution.secured ? "completed" : "failed", transfer: thrown?.releaseQuality === "delayedRelease" ? "delayed" : controlled ? "completed" : "notReached",
      firstThrow: thrown?.throwAttempted ? thrown.throwQuality === "offline" ? "failed" : "completed" : "notAttempted" },
    teammateLeg: { receiver: receiverReady ? "completed" : "notReached", ...(isDoublePlay ? {
      secondBaseReceive: relay.receive ? "completed" : "notCompleted", secondBasePivot: relay.turn ? "completed" : "notCompleted",
      secondBaseSecondThrow: relay.turn ? "completed" : "notCompleted", firstBaseReceive: relay.firstBaseReceive ? "completed" : "notCompleted" } : {}) },
    firstLegState: { status: firstOut ? "completed" : "failed", targetBase: selection?.route.targetBase || null },
    continuationState: { status: secondOut ? "completed" : firstOut && isDoublePlay ? "windowClosed" : "settledByActorOutcomes", targetBase: isDoublePlay ? "first" : null, window: continuationWindow },
    timingResolution: { firstLeg: runnerThrowTiming, firstLegSettlement, relayToFirstWindow: continuationWindow },
    ballContext: situation.ballContext.type, ballDirection: situation.ballDirection, ballDepth: situation.ballDepth,
    batterSpeed: situation.batterSpeed, runnerSpeed: Math.max(...situation.runnerSpeeds.filter(Number.isFinite), 0),
    ...situation.playerCapabilities, firstStage: secureResolution.margin ?? handoff.defensiveAccess.reachResolution.margin,
    secondStage: thrown?.accuracyMargin ?? 0, returnTiming: 0, windows: situation.windows
  });
  return { sample, choice: { routeId: choice.routeId, matchDecision: choice.matchDecision }, secureResolution,
    decisionThrowState,
    runnerThrowTiming, resolution: attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) };
}

function validateHighSchoolDecisionThrowState(match) {
  validateHighSchoolReceiverSourceMetadata(match);
  validateHighSchoolGroundLifecycleRoutes(match);
  const state = match?.groundBallInPlayState;
  if (state?.supported && !state.firstBaseContext && (state.firstBaseExecution
    || match.activeSituation?.contextSnapshot?.firstBaseContext
    || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence)) throw new Error("Invalid missing first-base participant context");
  if (state?.firstBaseContext) {
    if (!state.settlementApplied) assertHighSchoolGroundParticipant(match);
    if (state.firstBaseExecution) { validateHighSchoolFirstBaseExecution(match); return; }
    if (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence) throw new Error("Invalid incomplete first-base execution stages");
  }
  if (state?.supported && state.defensiveAccess?.playerPosition === "三壘手" && !state.thirdBaseExecution
    && (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.thirdBaseEvidence)) throw new Error("Invalid incomplete 3B execution stages");
  if (state?.thirdBaseExecution) {
    validateHighSchoolThirdBaseExecution(match);
    return;
  }
  if (!state?.decisionThrowState || state.settlementApplied || typeof DefensiveDecisionThrowFoundation === "undefined") return;
  if (state.shortstopExecution) {
    const stored = state.shortstopExecution;
    const choice = getInfieldDecisionChoice(match.defensiveSituation, match, stored.choice.matchDecision);
    if (!choice || choice.routeId !== stored.choice.routeId) throw new Error("Stale SS legal route");
    const fresh = buildHighSchoolShortstopExecution(match, match.defensiveSituation, choice, stored.sample);
    if (!stored.resolution.actionFacts) {
      // New facts are optional for historical executed saves. Validate every
      // pre-existing SS fact against reconstruction without rewriting the source.
      const { actionFacts, executionSample, ...historicalResolution } = fresh.resolution;
      fresh.resolution = historicalResolution;
    }
    if (JSON.stringify(fresh) !== JSON.stringify(stored)
      || JSON.stringify(state.secureResolution) !== JSON.stringify(fresh.secureResolution)
      || JSON.stringify(state.decisionThrowState) !== JSON.stringify(fresh.decisionThrowState)
      || JSON.stringify(state.runnerThrowTiming) !== JSON.stringify(fresh.runnerThrowTiming)) throw new Error("Stale SS execution / timing facts");
    const evidence = match.activeSituation?.resolution?.executionEvidence;
    if (evidence && Object.entries(stored.resolution).some(([key, value]) => {
      // Pre-action-contract saves can omit these additive facts. Every present
      // copy must agree with the reconstructed execution owner, not itself.
      if (["actionFacts", "executionSample"].includes(key) && !Object.prototype.hasOwnProperty.call(evidence, key)) return false;
      return JSON.stringify(evidence[key]) !== JSON.stringify(value);
    })) throw new Error("Stale SS lifecycle execution facts");
    return;
  }
  DefensiveDecisionThrowFoundation.validateStoredStage(state.decisionThrowState, getHighSchoolControlledDecisionInput(match, state));
  const evidence = match.activeSituation?.resolution?.executionEvidence;
  // Historical stages without the new contract retain their existing admission.
  if (evidence?.actionFacts) {
    if (!Number.isFinite(evidence.executionSample) || evidence.executionSample < 0 || evidence.executionSample >= 1) throw new Error("Invalid 2B execution sample");
    const routeId = match.activeSituation.decision?.selectedRoute || state.decisionThrowState.preControlIntent;
    const choice = generateInfieldLegalChoices(match.defensiveSituation, match).find(c => c.routeId === routeId);
    if (!choice) throw new Error("Stale 2B execution route");
    const raw = choice.routeId === "coverSecondFor643" ? resolveSecondBaseCoverage643(match.defensiveSituation, choice, evidence.executionSample)
      : resolveSecondBaseInitiatedRoute(match.defensiveSituation, choice, evidence.executionSample, match);
    const fresh = attachHighSchoolInfieldActionFacts(match, match.defensiveSituation, choice, raw, evidence.executionSample);
    if (JSON.stringify(fresh.actionFacts) !== JSON.stringify(evidence.actionFacts)
      || JSON.stringify(fresh.receiverResolution) !== JSON.stringify(evidence.receiverResolution)
      || fresh.outsCreated !== evidence.outsCreated || fresh.resultCode !== evidence.resultCode) throw new Error("Stale 2B receiver / action facts");
  }
  if (state.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    DefensiveRunnerThrowSettlementFoundation.validateProjectedTiming(state.runnerThrowTiming, state.decisionThrowState, state.runnerPhysicalStates,
      match.activeSituation?.resolution?.executionEvidence);
  }
}

function resolveHighSchoolYearOneMatch(decision, expectedMomentId = "", randomSource = Math.random) {
  const match = prepareCurrentHighSchoolYearOneMatch();
  if (match.simulationPhase === "offensive_agency_ready") {
    const agencySelection = decision === "agencyManual" ? "manual" : decision === "agencySimulate" ? "simulate" : "";
    return agencySelection ? chooseHighSchoolOffensiveAgency(agencySelection, expectedMomentId || match.offensivePlayerAgencyState?.momentId) : false;
  }
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match.activeSituation) : null;
  if (activeSituation?.type === "plateDecision") {
    if (expectedMomentId && expectedMomentId !== getHighSchoolYearOneMomentId(match)) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const resolvedPitch = resolveHighSchoolPlateDecisionPitch(match, legalRoute.routeId);
    if (!resolvedPitch) return false;
    const pitchText = formatHighSchoolPlateDecisionPitchResult(resolvedPitch.event);
    if (!resolvedPitch.plateAppearanceCompleted) return pitchText;
    const selectedChoice = resolvedPitch.selectedOffensiveChoice || match.plateDecisionState?.selectedOffensiveChoice;
    const completed = match.momentIndex === 0
      ? advanceHighSchoolYearOneAfterMomentOne(match, selectedChoice, null)
      : resolveHighSchoolYearOneFinalMoment(match, selectedChoice, null);
    return completed ? `${pitchText} ${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}` : false;
  }
  if (activeSituation?.type === "runnerTagUpDecision") {
    if (expectedMomentId && expectedMomentId !== match.currentMomentId) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const closed = resolveHighSchoolRunnerTagUpDecision(match, legalRoute.routeId, { randomSource });
    const outcome = match.lastClosedSituationSummary?.outcome || closed?.resolution?.reason || "";
    return outcome === "safeHome" ? "你衝回本壘得分。" : outcome === "taggedOutAtHome" ? "你在本壘前被觸殺出局。" : "你留在三壘。";
  }
  const currentMomentId = getHighSchoolYearOneMomentId(match);
  const legalChoices = getHighSchoolYearOneMatchMomentChoices(match);
  const legalChoice = legalChoices.find(choice => choice.matchDecision === decision);
  const expectedPhase = `moment_${match.momentIndex + 1}_ready`;
  if (match.completed || match.simulationPhase !== expectedPhase || !currentMomentId || (expectedMomentId && expectedMomentId !== currentMomentId) || !legalChoice) return false;
  if (match.completedMoments.some(moment => moment.id === currentMomentId)) return false;
  if (match.momentIndex === 0) {
    if (!advanceHighSchoolYearOneAfterMomentOne(match, legalChoice, null)) return false;
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  if (match.momentIndex === 1) {
    beginGroundBallSituationDecision(match, decision);
    const defensiveResolution = resolveHighSchoolDefensivePlay(match, decision, randomSource);
    recordGroundBallSituationResolution(match, defensiveResolution);
    const tier = defensiveResolution?.tier || "failure";
    advanceHighSchoolYearOneAfterMomentTwo(match, decision, tier, defensiveResolution);
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  return resolveHighSchoolYearOneFinalMoment(match, legalChoice, null);
}

function resolveReach(input = {}) {
  const op = binding(input);
  const identity = `${op.identity}|${op.primaryDefenderId}|reach-v1`;
  const ballDemand = demand(op);
  const caps = input.capabilities;
  const inputs = { reaction: ability(caps.reaction), range: ability(caps.range), mobility: ability(caps.mobility ?? caps.range) };
  const movement = inputs.range * 0.75 + inputs.mobility * 0.25;
  const variationIdentity = `${op.executionIdentity || op.identity}|${op.primaryDefenderId}|reach-v1`;
  const evidence = variation("reach", variationIdentity, input.roll);
  const margin = round(inputs.reaction * ballDemand.reactionWeight + movement * (1 - ballDemand.reactionWeight)
    - ballDemand.reachDemand + evidence.adjustment);
  return freeze({ version: VERSION, identity, opportunityIdentity: op.identity, physicalIdentity: op.physicalIdentity,
    defenderId: op.primaryDefenderId, position: op.primaryPosition, supported: true,
    authority: "physicalOpportunity+activeDefender+reachCapabilities",
    reachDemand: ballDemand.reachDemand, reactionDemand: ballDemand.reactionDemand, movementDemand: ballDemand.movementDemand,
    responsibilityClassification: op.responsibilityClassification, ballDemand, inputs, margin,
    reached: margin >= 0, reachQuality: margin >= 1.25 ? "cleanArrival" : margin >= 0 ? "stretchedArrival" : "notReached",
    variationEvidence: evidence });
}

function resolveSecure(input = {}) {
  const reach = validateReach(input);
  const base = secureBase(reach);
  if (!reach.reached) return freeze({ ...base, secureDemand: null, secureQuality: "notAttempted", secured: false,
    ballState: "notReached", variationEvidence: { namespace: RNG_NAMESPACES.secure, consumed: false, roll: null } });
  const ball = input.opportunity.ballContext;
  const fielding = ability(input.capabilities.fielding ?? input.capabilities.catching);
  const catching = ability(input.capabilities.catching ?? input.capabilities.fielding);
  const ground = ball.ballType === "groundBall";
  const pressure = { weak: 2.5, moderate: 3.5, firm: 4.5, hard: 6 }[ball.pace]
    + (ball.ballType === "lineDrive" ? 1 : ball.ballType === "flyBall" ? -1 : 0);
  const arrivalPenalty = reach.reachQuality === "stretchedArrival" ? 2 : 0;
  const secureDemand = pressure + arrivalPenalty;
  const variationIdentity = `${reach.variationEvidence?.identity || reach.identity}|secure-v1`;
  const evidence = variation("secure", variationIdentity, input.roll);
  const margin = round((ground ? fielding * 0.75 + catching * 0.25 : catching * 0.8 + fielding * 0.2)
    - secureDemand + evidence.adjustment);
  const secured = margin >= 0;
  return freeze({ ...base, secureDemand, margin, secured,
    secureQuality: ground ? (margin >= 1.5 ? "cleanControl" : secured ? "bobbleButControlled" : "notControlled")
      : secured ? "caughtBeforeGround" : "notCaught",
    ballState: secured ? "secured" : ground ? "looseLiveBall" : "groundContactLive",
    inputs: { ...base.inputs, fielding, catching, ballType: ball.ballType, pace: ball.pace, pressure, arrivalPenalty },
    variationEvidence: evidence });
}
// Existing 2B control remains the sole control authority for that validated vertical.
// This adapter records its physical fact; it never rolls or interprets outs/throws.

function projectAccess(reach) {
  const supported = reach?.supported === true && reach.reached === true;
  const level = !supported ? "unsupported" : reach.reachQuality === "cleanArrival" ? "favored" : "possible";
  return freeze({ supported, level, score: level === "favored" ? 3 : supported ? 2 : 0,
    reason: supported ? "canonicalReachArrival" : "canonicalReachUnavailable", reachIdentity: reach?.identity || "",
    reachResolution: reach ? copy(reach) : null });
}

function normalizeSave(saved) {
  const sourceSaveVersion = saved.saveVersion;
  // Raw owner validation precedes defaults, Object.assign and generic normalizers.
  if (typeof ReceiverSourceSnapshot !== "undefined") ReceiverSourceSnapshot.validateRawSave(saved);
  else if (sourceSaveVersion === 16 || saved.receiverSourceSaveFormatVersion || saved.highSchoolMatch?.receiverSourceFormatVersion) {
    throw new Error("Receiver source snapshot module required for new Save format");
  }
  const fresh = createInitialPlayer(saved.name || "");
  Object.assign(fresh, saved);
  if (typeof HighSchoolExchangeNetwork !== "undefined") {
    fresh.highSchoolExchangeNetwork = HighSchoolExchangeNetwork.normalizeState(saved.highSchoolExchangeNetwork);
  } else if (saved.highSchoolExchangeNetwork?.evidence?.length) throw new Error("Exchange network module required to restore evidence");
  if (typeof HighSchoolScheduleOpportunity !== "undefined") {
    fresh.highSchoolSchedule = HighSchoolScheduleOpportunity.normalizeState(saved.highSchoolSchedule);
  }
  const savedPrimaryPosition = saved.primaryPosition !== undefined ? saved.primaryPosition : saved.seasonPosition;
  const savedSecondaryPositions = Array.isArray(saved.secondaryPositions)
    ? saved.secondaryPositions
    : saved.secondaryPosition ? [saved.secondaryPosition] : [];
  applyCanonicalPositionProfile(fresh, savedPrimaryPosition || "", savedSecondaryPositions);
  fresh.bats = PlayerIdentityOptions.bats.includes(saved.bats) ? saved.bats : "R";
  fresh.throws = PlayerIdentityOptions.throws.includes(saved.throws) ? saved.throws : "R";
  const legacyIdealSelfMap = {
    "技術鑽研型": "技巧型",
    "直覺天賦型": "全能型",
    "關鍵時刻型": "強打型",
    "團隊核心型": "棒球理解型"
  };
  if (sourceSaveVersion < 15 && legacyIdealSelfMap[fresh.idealSelf]) fresh.idealSelf = legacyIdealSelfMap[fresh.idealSelf];
  const defaultGenesis = createInitialPlayer().characterGenesis;
  fresh.characterGenesis = Object.assign({}, defaultGenesis, saved.characterGenesis || {});
  fresh.characterGenesis.baseRoll = Object.assign({}, defaultGenesis.baseRoll, saved.characterGenesis?.baseRoll || {});
  fresh.characterGenesis.allocation = Object.assign({}, defaultGenesis.allocation, saved.characterGenesis?.allocation || {});
  fresh.characterGenesis.finalAbilities = Object.assign({}, defaultGenesis.finalAbilities, saved.characterGenesis?.finalAbilities || {});
  if (sourceSaveVersion < 15 && fresh.name && !saved.characterGenesis) {
    fresh.characterGenesis.completed = true;
    fresh.characterGenesis.shape = "舊存檔沿用既有成長";
    fresh.characterGenesis.archetype = fresh.idealSelf || "全能型";
    fresh.characterGenesis.initialAspiration = fresh.origin || PlayerIdentityOptions.origins[0];
  }
  if (saved.highSchoolYearTwoStep === undefined) fresh.highSchoolYearTwoStep = 0;
  if (saved.highSchoolYearTwoResult === undefined) fresh.highSchoolYearTwoResult = "";
  if (saved.highSchoolYearTwoDetail === undefined) fresh.highSchoolYearTwoDetail = "";
  fresh.baseballSkills = Object.assign({}, createInitialPlayer().baseballSkills, saved.baseballSkills || {});
  const capabilityState = ensureCapabilityStateShape(fresh);
  const hasVersionedInitialCapability = capabilityState.initialSkillFormulaVersion === INITIAL_SKILL_FORMULA_VERSION
    && UNIVERSAL_BASEBALL_SKILL_KEYS.every(skill => Number.isFinite(Number(capabilityState.initialBaseballSkills?.[skill])) && Number(capabilityState.initialBaseballSkills[skill]) >= 1);
  if (!hasVersionedInitialCapability) {
    const migration = migrateLegacyPlayerCapability(fresh, { sourceSaveVersion });
    if (!migration.ok) throw new Error(`舊存檔 Capability migration 失敗：${migration.error}`);
  }
  else {
    const reachedHighSchool = Number(fresh.age) >= 16 || String(fresh.chapter || "").includes("青棒") || Number(fresh.highSchoolStep) > 0;
    if (reachedHighSchool && capabilityState.initialized !== true) {
      const settlement = settleHighSchoolEntryCapability(fresh, { originType: capabilityState.originType || "save-reload-settlement" });
      if (!settlement.ok) throw new Error(`存檔 Capability settlement 失敗：${settlement.error}`);
    }
  }
  fresh.developmentState = ensureDevelopmentStateShape(fresh, saved.developmentState || null, {
    migrateMissing: true,
    sourceSaveVersion
  });
  fresh.schoolInvitationState = restoreSchoolInvitationState(saved.schoolInvitationState);

